[URL Rewrite]
request if ${url} ~= /^https?:\/\/img\.admobile\.top\/admobile-adRequest\/.*.(jpg|png)/i then reject(200)
request if ${url} ~= /^https?:\/\/webcdn\.m\.qq\.com\/qiantu\/upload\/202[0-9]{5}\/.*.(jpg|png)/i then reject(200)

[Rule]
DOMAIN-KEYWORD,image.bianxianmao.com,REJECT

[MITM]
hostname = %APPEND% img.admobile.top, webcdn.m.qq.com
